INSERT INTO profiles (user_id,age,gender,city,budget_min,budget_max,sleep_slot,cleanliness,smoking,drinking,pets,languages,bio,photo,ok_smoking,ok_drinking,ok_pets,min_cleanliness,sleep_flex) VALUES
((SELECT id FROM users WHERE email='aarav.kulkarni@example.com'),26,'male','Bengaluru',16000,24000,2,5,'no','yes','no','English,Hindi,Kannada','I build distributed systems by day and read sci-fi or brew pour-over coffee by night. I keep common areas spotless, use headphones for meetings, and value mutual privacy.','avatar:c01','no','yes','no',4,1),
((SELECT id FROM users WHERE email='ananya.deshmukh@example.com'),24,'female','Bengaluru',15000,22000,4,3,'no','yes','no','English,Hindi,Kannada','Design sprints keep me sketching late with lo-fi playlists on low volume. Looking for an easygoing female flatmate who loves plants, good chai, and zero micromanagement.','avatar:c02','no','yes','yes',3,1),
((SELECT id FROM users WHERE email='karthik.subramanian@example.com'),28,'male','Bengaluru',20000,30000,2,5,'no','no','no','English,Hindi,Kannada','Already leased a spacious 3BHK in HSR Sector 2 with a great balcony. Up by 5:30 AM for Agara Lake runs, strict vegetarian kitchen, and peaceful weekday evenings.','avatar:c03','no','no','no',4,1),
((SELECT id FROM users WHERE email='meera.nair@example.com'),23,'female','Bengaluru',11000,16000,3,4,'no','yes','no','English,Hindi,Kannada','Moving to Bengaluru for my final year! I love hosting Catan nights on Saturdays, trying new Kerala recipes, and keeping a warm, friendly home vibe rather than living like strangers.','avatar:c04','no','yes','yes',3,2),
((SELECT id FROM users WHERE email='rohan.chatterjee@example.com'),30,'male','Bengaluru',25000,38000,2,4,'yes','yes','no','English,Hindi,Kannada','I fly out most Monday mornings and return Thursday nights. Looking for a premium gated society apartment in Whitefield with zero clutter and reliable security.','avatar:c05','maybe','yes','no',4,1),
((SELECT id FROM users WHERE email='siddharth.joshi@example.com'),25,'male','Pune',12000,18000,3,3,'yes','yes','no','English,Hindi,Marathi','Pretty laid-back guy—on-call rotations happen once a month, otherwise I am out trekking on weekends or gaming with a headset. Happy to split a cook and maid.','avatar:c06','maybe','yes','yes',3,1),
((SELECT id FROM users WHERE email='rutuja.patwardhan@example.com'),22,'female','Pune',7500,11500,2,4,'no','no','no','English,Hindi,Marathi','Preparing for campus placements and building my capstone project. Need a tidy, focused environment with respectful female flatmates and easy access to public transport.','avatar:c07','no','no','no',4,1),
((SELECT id FROM users WHERE email='kabir.malhotra@example.com'),27,'male','Pune',13000,19000,2,5,'no','yes','no','English,Hindi,Marathi','I hit the gym at 6 AM sharp and prep high-protein meals in batches. Looking for a clean flat near EON IT Park with ample kitchen counter space and good ventilation.','avatar:c08','no','yes','no',4,1),
((SELECT id FROM users WHERE email='sneha.gokhale@example.com'),29,'female','Pune',16000,23000,2,5,'no','no','no','English,Hindi,Marathi','My work involves deep listening all day, so home is my quiet sanctuary. I love classical music, reading on the balcony, and sharing occasional cups of herbal tea.','avatar:c09','no','no','yes',4,1),
((SELECT id FROM users WHERE email='aditya.sawant@example.com'),24,'male','Mumbai',24000,35000,3,4,'yes','yes','no','English,Hindi,Marathi','Long weekday hours mean I am mostly home just to sleep and recharge. Looking for a well-maintained flat with short commute times and zero household drama.','avatar:c10','maybe','yes','no',4,1),
((SELECT id FROM users WHERE email='zara.sheikh@example.com'),26,'female','Mumbai',22000,32000,3,4,'yes','yes','no','English,Hindi,Marathi','I already have a bright, breezy 2BHK off Turner Road! Love hosting small wine-and-cheese evenings on Fridays, obsessed with clean interiors, and super welcoming.','avatar:c11','maybe','yes','yes',4,1),
((SELECT id FROM users WHERE email='pranav.menon@example.com'),21,'male','Mumbai',14000,20000,4,3,'yes','yes','no','English,Hindi,Marathi','Interning at a production house while finishing college. I practice unplugged guitar with headphones or before 8 PM, love late-night Maggi runs, and am super adaptable.','avatar:c12','maybe','yes','yes',2,1),
((SELECT id FROM users WHERE email='kavita.iyer@example.com'),31,'female','Mumbai',26000,38000,2,5,'no','no','no','English,Hindi,Marathi','Irregular hospital shifts mean I sometimes sleep during the day. Looking for a mature, empathetic female flatmate who values silence, hygiene, and personal boundaries.','avatar:c01','no','no','no',5,4),
((SELECT id FROM users WHERE email='devansh.verma@example.com'),25,'male','Delhi',9000,14000,2,4,'no','no','no','English,Hindi','Up at 5:30 AM every morning with a strict study timetable. Looking for a fellow aspirant or quiet working professional who respects library-level silence.','avatar:c02','no','no','no',4,1),
((SELECT id FROM users WHERE email='mehak.kapoor@example.com'),23,'female','Delhi',13000,19000,3,4,'no','yes','no','English,Hindi','I love baking banana bread on Sundays, exploring cafes in Safdarjung, and keeping a cheerful home. Looking for a warm, clean female flatmate around South Delhi.','avatar:c03','no','yes','yes',4,2),
((SELECT id FROM users WHERE email='arjun.bhatia@example.com'),28,'male','Gurugram',20000,30000,2,5,'no','yes','no','English,Hindi','Have a great high-rise apartment with power backup, gym, and pool. I work hybrid, hit the gym in the evenings, and enjoy relaxed F1 watch parties on Sundays.','avatar:c04','no','yes','no',4,1),
((SELECT id FROM users WHERE email='niharika.saxena@example.com'),25,'female','Gurugram',18000,26000,3,5,'yes','yes','no','English,Hindi','Predictable late-ish evenings during deal closings, followed by quiet weekends with a good novel. Looking for someone mature, tidy, and financially reliable.','avatar:c05','maybe','yes','no',4,1),
((SELECT id FROM users WHERE email='tushar.agarwal@example.com'),24,'male','Noida',10000,15500,4,4,'no','no','no','English,Hindi','Mostly glued to my dual-monitor setup coding or watching anime. Very quiet, never throw parties, and always pay bills on day one.','avatar:c06','no','no','no',4,1),
((SELECT id FROM users WHERE email='kritika.srivastava@example.com'),26,'female','Noida',11500,17000,2,5,'no','no','no','English,Hindi','I have 12 indoor plants and a calm daily routine built around morning yoga and evening cooking. Looking for a warm, neat female roommate.','avatar:c07','no','no','yes',4,1),
((SELECT id FROM users WHERE email='saiteja.reddy@example.com'),27,'male','Hyderabad',15000,22000,2,4,'no','yes','no','English,Hindi,Telugu','Easygoing Hyderabadi who plays badminton every evening and loves weekend road trips. Looking for two friendly tech folks to share a spacious gated flat.','avatar:c08','no','yes','no',3,2),
((SELECT id FROM users WHERE email='divya.krishnan@example.com'),24,'female','Hyderabad',12000,17500,2,5,'no','no','no','English,Hindi,Telugu','Organized, punctual, and respectful of shared spaces. I practice dance at an academy twice a week and love cooking South Indian comfort food.','avatar:c09','no','no','no',4,1),
((SELECT id FROM users WHERE email='nikhil.varma@example.com'),29,'male','Hyderabad',16000,24000,2,4,'no','yes','yes','English,Hindi,Telugu','I have a calm 4-year-old Golden Retriever named Bruno and a sunny 2BHK. Looking for a genuine animal lover who enjoys a peaceful, well-kept home.','avatar:c10','no','yes','yes',4,1),
((SELECT id FROM users WHERE email='yashwant.chouhan@example.com'),22,'male','Indore',5500,8500,3,4,'no','no','no','English,Hindi','Interning at a startup in Vijay Nagar while completing my final semester. Friendly, neat, love late-evening Sarafa food walks, and keep study hours quiet.','avatar:c11','no','no','no',3,1),
((SELECT id FROM users WHERE email='sakshi.tiwari@example.com'),25,'female','Indore',8500,13000,2,5,'no','no','no','English,Hindi','Audit seasons keep me busy, so I appreciate an organized home where chores happen on schedule. Early riser, vegetarian, and love weekend family visits.','avatar:c12','no','no','no',5,1),
((SELECT id FROM users WHERE email='harshit.patidar@example.com'),27,'male','Indore',9500,14500,2,4,'no','yes','no','English,Hindi','Already set up a great 3BHK near Mahalaxmi Nagar / Nipania with high-speed fiber and washing machine. Social cook on weekends, chill during the week.','avatar:c01','maybe','yes','no',3,2),
((SELECT id FROM users WHERE email='pranati.mishra@example.com'),23,'female','Bhopal',6000,9500,3,3,'no','no','no','English,Hindi','Model-making and studio critiques keep me up late, though I work silently with desk lamps. Love cycling by Upper Lake on Sunday mornings.','avatar:c02','no','no','yes',3,1),
((SELECT id FROM users WHERE email='vigneshwaran.r@example.com'),26,'male','Chennai',11000,16500,2,5,'no','no','no','English,Tamil','Calm, methodical, and appreciative of a clean, peaceful flat. I work on hardware firmware, enjoy Carnatic concerts in December, and never bring noise home.','avatar:c03','no','no','no',5,1),
