((SELECT id FROM users WHERE email='parthiv.shah@example.com'),28,'male','Ahmedabad',9500,14500,2,5,'no','no','no','English,Gujarati,Hindi','Early sleeper, cycling enthusiast, and strict Jain/vegetarian. Looking for a tidy, respectful flatmate in a gated society near SG Highway.','avatar:c05','no','no','no',4,1),
