 ids AS (SELECT (SELECT id FROM users WHERE email=a) ua,(SELECT id FROM users WHERE email=b) ub FROM e)
INSERT INTO swipes (swiper_id,swiped_id,direction,created_at)
SELECT ua,ub,'like',now()-interval '3 day' FROM ids UNION ALL SELECT ub,ua,'like',now()-interval '2 day' FROM ids
ON CONFLICT DO NOTHING;
INSERT INTO matches (user1_id,user2_id,created_at)
SELECT LEAST(s.swiper_id,s.swiped_id),GREATEST(s.swiper_id,s.swiped_id),now()-interval '2 day'
FROM swipes s JOIN swipes t ON t.swiper_id=s.swiped_id AND t.swiped_id=s.swiper_id AND t.direction='like'
JOIN users u ON u.id=s.swiper_id WHERE s.direction='like' AND s.swiper_id<s.swiped_id AND u.email LIKE '%@example.com'
ON CONFLICT DO NOTHING;
-- pending requests and passes
INSERT INTO swipes (swiper_id,swiped_id,direction)
SELECT (SELECT id FROM users WHERE email=a),(SELECT id FROM users WHERE email=b),d FROM (VALUES
 ('rohan.chatterjee@example.com','aarav.kulkarni@example.com','like'),('rutuja.patwardhan@example.com','sneha.gokhale@example.com','like'),
 ('pranav.menon@example.com','aditya.sawant@example.com','like'),('kavita.iyer@example.com','pranav.menon@example.com','pass'),
 ('sakshi.tiwari@example.com','harshit.patidar@example.com','like'),('mehak.kapoor@example.com','devansh.verma@example.com','pass')) v(a,b,d)
ON CONFLICT DO NOTHING;
-- a few messages in every new match
INSERT INTO messages (match_id,sender_id,body,created_at,read_at)
SELECT m.id, x.who, x.body, now()-interval '1 day'+x.k*interval '4 min', now()
FROM matches m JOIN users u ON u.id=m.user1_id AND u.email LIKE '%@example.com'
CROSS JOIN LATERAL (VALUES (1,m.user1_id,'Hey! Saw we matched. Still looking for a place?'),
 (2,m.user2_id,'Yes! Budget-wise we look close. When do you usually sleep?'),
 (3,m.user1_id,'Around 11. Shall we check a couple of flats this weekend?')) x(k,who,body);
